import{_ as i}from"./chunks/项目表关系.BXf7dev0.js";import{_ as a}from"./chunks/工作项全部-1700.DkciBB_n.js";import{_ as t,o as e,c as n,a2 as p}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E8%BF%AD%E4%BB%A3%E8%AF%A6%E6%83%85-1700.Bw9Jrhrj.png",h="/newx-doc/assets/%E6%95%8F%E6%8D%B7%E5%BE%85%E8%A7%84%E5%88%92-1700.apqwePPC.png",o="/newx-doc/assets/%E6%95%8F%E6%8D%B7%E7%94%98%E7%89%B9%E5%9B%BE-1700.CFaHhD2E.png",r="/newx-doc/assets/%E6%95%8F%E6%8D%B7%E5%B7%A5%E6%97%B6-1700.aKDgCmN1.png",l="/newx-doc/assets/%E5%BC%80%E5%A7%8B%E8%BF%AD%E4%BB%A3-1700.EFMntJTp.png",k="/newx-doc/assets/%E5%BC%80%E5%A7%8B%E8%BF%AD%E4%BB%A3-1700.EFMntJTp.png",c="/newx-doc/assets/%E5%BC%80%E5%A7%8B%E8%BF%AD%E4%BB%A3-1700.EFMntJTp.png",E="/newx-doc/assets/%E8%BF%AD%E4%BB%A3%E8%AF%A6%E6%83%85-1700.Bw9Jrhrj.png",D=JSON.parse('{"title":"【项目中心】项目详情与迭代","description":"","frontmatter":{},"headers":[],"relativePath":"pms/pm/project/detail.md","filePath":"pms/pm/project/detail.md","lastUpdated":null}'),g={name:"pms/pm/project/detail.md"};function F(m,s,y,u,_,A){return e(),n("div",null,[...s[0]||(s[0]=[p('<h1 id="【项目中心】项目详情与迭代" tabindex="-1">【项目中心】项目详情与迭代 <a class="header-anchor" href="#【项目中心】项目详情与迭代" aria-label="Permalink to &quot;【项目中心】项目详情与迭代&quot;">​</a></h1><p>项目详情与迭代属于项目中心，由 <code>yudao-module-pms</code> 后端模块的 <code>pm.project</code>、<code>pm.iteration</code> 包实现，前端实现在 <code>@/views/pms/pm/project/detail</code> 和 <code>@/views/pms/pm/iteration</code> 目录。</p><p>项目详情是项目执行的统一入口。通用项目围绕「<strong>项目概况 → 任务 → 甘特图</strong>」展开，敏捷开发项目增加「<strong>待规划 → 迭代 → 全部事项 → 需求 / 任务 / 缺陷 → 工时</strong>」页签。</p><ul><li><strong>项目概况</strong>：展示公告、项目基本信息、完成趋势、未完成迭代和分配给当前用户的工作项。</li><li><strong>待规划</strong>：敏捷项目可以把 Backlog 工作项拖入迭代，也可以在迭代内直接创建工作项。</li><li><strong>迭代</strong>：维护迭代周期、目标、负责人和状态，进入迭代详情查看事项分布、趋势和燃尽数据。</li><li><strong>甘特图与工时</strong>：从工作项的开始 / 截止时间绘制时间轴，从工时记录聚合项目日报。</li></ul><p>本文涉及表如下图所示：</p><p><img src="'+i+'" alt="项目详情与迭代表关系"></p><h2 id="_1-取数来源" tabindex="-1">1. 取数来源 <a class="header-anchor" href="#_1-取数来源" aria-label="Permalink to &quot;1. 取数来源&quot;">​</a></h2><p>项目详情、概况、待规划看板和甘特图<strong>没有独立的展示表</strong>，涉及的数据表如下：</p><table tabindex="0"><thead><tr><th>表</th><th>关系与用途</th></tr></thead><tbody><tr><td><code>pms_project</code></td><td>保存项目名称、类型、可见范围、周期、状态和最近访问时间</td></tr><tr><td><code>pms_project_announcement</code></td><td>保存项目公告，项目概况只展示最新一条</td></tr><tr><td><code>pms_project_member</code></td><td>保存项目成员级别，决定详情页是否可编辑，以及负责人下拉的可选范围</td></tr><tr><td><code>pms_iteration</code></td><td>保存迭代周期、目标、负责人和状态，是待规划和甘特图的分组依据</td></tr><tr><td><code>pms_work_item</code></td><td>保存工作项的状态、负责人、迭代、父子关系和起止时间，是概况、待规划和甘特图的数据源</td></tr><tr><td><code>pms_work_item_work_log</code></td><td>保存工时记录，是项目工时报表的数据源</td></tr></tbody></table><p>本篇只展开 <code>pms_iteration</code>，详见 <a href="#_3-1-表结构">§3.1 表结构</a>。</p><h2 id="_2-项目详情" tabindex="-1">2. 项目详情 <a class="header-anchor" href="#_2-项目详情" aria-label="Permalink to &quot;2. 项目详情&quot;">​</a></h2><p>项目详情，由 PmsProjectController 提供接口（<code>/pms/pm/project</code>），页签数据由工作项和迭代接口提供。</p><h3 id="_2-1-管理后台" tabindex="-1">2.1 管理后台 <a class="header-anchor" href="#_2-1-管理后台" aria-label="Permalink to &quot;2.1 管理后台&quot;">​</a></h3><p>对应 [PMS 项目管理 -&gt; 项目中心 -&gt; 我的项目] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/pms/pm/project/detail</code> 目录，主要子组件为 <code>ProjectOverview.vue</code>、<code>PlanningBoard.vue</code>、<code>ProjectGantt.vue</code> 和 <code>ProjectWorkLog.vue</code>。</p><h4 id="项目概况" tabindex="-1">项目概况 <a class="header-anchor" href="#项目概况" aria-label="Permalink to &quot;项目概况&quot;">​</a></h4><p>点击「我的项目」中的项目名称进入详情，进入时会<strong>更新项目的最近访问时间</strong>，用于项目列表按最近访问排序。</p><p>页面展示项目名称、项目类型、可见范围、周期、描述、项目进度、成员数量和最新公告。通用项目展示近 14 日完成趋势，敏捷项目展示未完成迭代卡片和状态。「分配给我的」区域展示当前用户未完成的工作项，点击标题打开 <code>WorkItemDetail.vue</code>。</p><p><img src="'+d+'" alt="管理后台 - 项目概况"></p><h4 id="待规划" tabindex="-1">待规划 <a class="header-anchor" href="#待规划" aria-label="Permalink to &quot;待规划&quot;">​</a></h4><p>敏捷项目进入「待规划」页签后，<code>PlanningBoard.vue</code> 左侧展示未规划的 Backlog 工作项，右侧按未完成迭代分组展示已规划的工作项。</p><p>拖拽工作项进入迭代时，先调用 <code>updateWorkItemIteration</code> 修改所属迭代，再调用 <code>updateWorkItemPlanningSort</code> 保存目标区域顺序；拖回 Backlog 时把 <code>iterationId</code> 置空。<strong>有筛选条件时页面会禁用拖拽</strong>，避免把局部结果覆盖完整排序。</p><p>Backlog 和迭代内均支持快速创建工作项，迭代标题旁可以快速创建迭代。</p><p><img src="'+h+'" alt="管理后台 - 敏捷待规划"></p><h4 id="事项页签" tabindex="-1">事项页签 <a class="header-anchor" href="#事项页签" aria-label="Permalink to &quot;事项页签&quot;">​</a></h4><p>「全部事项」使用 <code>WorkItemAllList.vue</code>，需求、任务和缺陷分别使用 <code>WorkItemList.vue</code>。通用项目只显示任务；敏捷项目按工作项类型切换需求、任务和缺陷。点击事项标题打开工作项详情抽屉，详见 <a href="./../work-item">《【项目中心】工作项与协作》</a>。</p><p><img src="'+a+'" alt="管理后台 - 全部事项"></p><h4 id="甘特图" tabindex="-1">甘特图 <a class="header-anchor" href="#甘特图" aria-label="Permalink to &quot;甘特图&quot;">​</a></h4><p><code>ProjectGantt.vue</code> 并行加载项目全部工作项和敏捷项目迭代，<strong>只展示同时填写开始时间和截止时间的工作项</strong>。页面支持标题关键词、日期范围和日 / 周 / 月 / 年视图；敏捷项目按迭代和待规划分组，并支持父子工作项折叠。</p><p>甘特图数据仍来自工作项和迭代的分页接口，<strong>没有独立的甘特图表</strong>。</p><p><img src="'+o+'" alt="管理后台 - 项目甘特图"></p><h4 id="工时" tabindex="-1">工时 <a class="header-anchor" href="#工时" aria-label="Permalink to &quot;工时&quot;">​</a></h4><p>敏捷项目的「工时」页签使用 <code>ProjectWorkLog.vue</code>，由 <code>getWorkLogProjectReport</code> 按迭代、工作项和日期聚合实际投入时长。默认日期范围为<strong>本月第一天至今天</strong>，支持按迭代名称和日期范围筛选，点击工作项可打开详情。</p><p>没有迭代的工作项归入「未规划事项」分组。工时表结构和登记规则详见 <a href="./../work-item">《【项目中心】工作项与协作》</a>。</p><p><img src="'+r+'" alt="管理后台 - 项目工时"></p><h2 id="_3-迭代" tabindex="-1">3. 迭代 <a class="header-anchor" href="#_3-迭代" aria-label="Permalink to &quot;3. 迭代&quot;">​</a></h2><p>迭代，由 PmsIterationController 提供接口（<code>/pms/pm/iteration</code>）。迭代只属于一个项目，工作项通过 <code>iteration_id</code> 关联迭代。</p><h3 id="_3-1-表结构" tabindex="-1">3.1 表结构 <a class="header-anchor" href="#_3-1-表结构" aria-label="Permalink to &quot;3.1 表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pms_iteration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `project_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;项目编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `owner_user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;负责人用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `name`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;迭代名称&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `target`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;迭代目标&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `description`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;迭代描述&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `start_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;开始时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `end_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;结束时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `finish_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;完成时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `sort`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;显示顺序&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;状态&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PMS 迭代&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>project_id</code> 关联 <code>pms_project</code> 表的 <code>id</code> 字段，<code>owner_user_id</code> 关联 <code>system_users</code> 表的 <code>id</code> 字段。负责人的<strong>可选范围由当前项目成员决定</strong>，PMS 不复制后台账号表，也不把负责人写成独立的员工或部门记录。</p><p>② <code>start_time</code>、<code>end_time</code> 可以同时为空；填写周期时必须同时填写，且开始时间早于结束时间。<strong>开始迭代时会再次要求两者均有值</strong>；完成迭代时写入 <code>finish_time</code>。</p><p>③ <code>sort</code> 是项目内的迭代顺序，创建时按项目现有最大顺序递增。列表排序会补充 <code>id</code> 作为稳定的次级排序。</p><p>④ 枚举 <code>status</code> 迭代状态（<code>PmsIterationStatusEnum</code>）。详见 <a href="#_3-2-状态流转">§3.2 状态流转</a>。</p><h3 id="_3-2-状态流转" tabindex="-1">3.2 状态流转 <a class="header-anchor" href="#_3-2-状态流转" aria-label="Permalink to &quot;3.2 状态流转&quot;">​</a></h3><p>迭代生命周期由 PmsIterationServiceImpl 控制。状态字段为 <code>status</code>：</p><table tabindex="0"><thead><tr><th>状态值</th><th>枚举</th><th>说明</th><th>可执行操作</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>PLANNED</code></td><td>未开始</td><td>编辑、开始迭代、删除</td></tr><tr><td><code>2</code></td><td><code>ACTIVE</code></td><td>进行中</td><td>编辑、完成迭代、删除</td></tr><tr><td><code>3</code></td><td><code>COMPLETED</code></td><td>已完成</td><td>编辑、删除</td></tr></tbody></table><p>状态流转说明</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新建迭代 ──→ 未开始(1) ──开始──→ 进行中(2) ──完成──→ 已完成(3)</span></span>\n<span class="line"><span>              │              │                  │</span></span>\n<span class="line"><span>              └──────────────┴────── 删除 ───────┘</span></span></code></pre></div><ul><li><strong>创建</strong>（<code>createIteration</code>）：Service 强制设置为未开始，创建请求<strong>不能自行传入状态</strong>，同时校验项目处于进行中。</li><li><strong>开始</strong>（<code>startIteration</code>）：只允许未开始迭代，补充开始和截止时间后变为进行中。开始后，待规划看板才会把该迭代作为可拖入目标。</li><li><strong>完成</strong>（<code>completeIteration</code>）：只允许进行中迭代，写入完成时间。<strong>完成后工作项仍保留在该迭代中</strong>，项目处于进行中且用户有写权限时，仍可按项目写权限继续新增和编辑。</li><li><strong>删除</strong>（<code>deleteIteration</code>）：项目处于进行中且当前用户有项目写权限时，<strong>任意状态的迭代都可以删除</strong>。删除前会把关联工作项的 <code>iteration_id</code> 置空，<strong>不删除工作项</strong>。</li><li><strong>项目锁定</strong>：项目归档或移入回收站后，所有迭代操作均不可用。</li></ul><h3 id="_3-3-管理后台" tabindex="-1">3.3 管理后台 <a class="header-anchor" href="#_3-3-管理后台" aria-label="Permalink to &quot;3.3 管理后台&quot;">​</a></h3><p>对应 [PMS 项目管理 -&gt; 项目中心 -&gt; 我的项目 -&gt; 项目详情 -&gt; 迭代] 页签，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/pms/pm/iteration</code> 目录。</p><h4 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h4><p><code>IterationList.vue</code> 支持按迭代名称和状态筛选，展示编号、名称、状态、进度、负责人和起止日期。点击名称进入隐藏路由 <code>/pms/pm/iteration/detail/:id</code>。</p><p><img src="'+l+'" alt="管理后台 - 迭代列表"></p><h4 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h4><p>点击【新建迭代】打开 <code>IterationForm.vue</code>，填写迭代名称、负责人、开始时间、截止时间、目标和描述。项目编号由详情页传入，状态由后端初始化，负责人只能从项目成员中选择。</p><p><img src="'+k+'" alt="管理后台 - 新增迭代"></p><h4 id="修改" tabindex="-1">修改 <a class="header-anchor" href="#修改" aria-label="Permalink to &quot;修改&quot;">​</a></h4><p>任意状态的迭代都可以点击【编辑】打开同一个 <code>IterationForm.vue</code>。保存时后端不修改项目编号和迭代状态。</p><h4 id="开始与完成" tabindex="-1">开始与完成 <a class="header-anchor" href="#开始与完成" aria-label="Permalink to &quot;开始与完成&quot;">​</a></h4><p>未开始迭代点击【开始迭代】打开 <code>IterationStartForm.vue</code>，填写周期后调用 <code>startIteration</code>。进行中迭代点击【完成迭代】并二次确认后调用 <code>completeIteration</code>。</p><p><img src="'+c+'" alt="管理后台 - 开始迭代"></p><h4 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to &quot;删除&quot;">​</a></h4><p>点击【删除】并二次确认后，Service 先把该迭代下工作项的 <code>iteration_id</code> 置空，再删除迭代记录。这些工作项会<strong>回到待规划区域</strong>，不会被一起删除。</p><h4 id="详情" tabindex="-1">详情 <a class="header-anchor" href="#详情" aria-label="Permalink to &quot;详情&quot;">​</a></h4><p>点击迭代名称进入 <code>/pms/pm/iteration/detail/:id</code>，展示事项总数、状态分布、事项类型分布、近 14 日趋势、燃尽数据和最近动态；敏捷项目详情还提供全部、需求、任务、缺陷页签。</p><p><img src="'+E+'" alt="管理后台 - 迭代详情"></p>',67)])])}const P=t(g,[["render",F]]);export{D as __pageData,P as default};
